input_grid = [[int(x) for x in row.split()] for row in test_input_str.strip().split('\n')]
height, width = len(input_grid), len(input_grid[0])

freq = {}
for row in input_grid:
    for v in row:
        freq[v] = freq.get(v, 0) + 1

most_val = max(freq.keys(), key=lambda k: freq[k])

output_grid = []
for i in range(height):
    row_out = []
    for j in range(width):
        val = input_grid[i][j]

